import{clampPoint}from'./models.js';
export class DrawBoard{
 constructor(canvas,{guide='lines',trace='',onChange=()=>{},onStatus=()=>{}}={}){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.guide=guide;this.trace=trace;this.onChange=onChange;this.onStatus=onStatus;this.color='#235a45';this.tool='brush';this.width=7;this.showGuide=true;this.items=[];this.cursor=[400,250];this.pen=false;this.active=null;this.abort=new AbortController();canvas.width=800;canvas.height=500;const listen=(name,fn)=>canvas.addEventListener(name,fn,{signal:this.abort.signal});listen('pointerdown',e=>{if(e.button!==0)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);const p=this.point(e);this.cursor=p;if(this.tool==='brush'){this.active={type:'stroke',color:this.color,width:this.width,points:[p]};this.items.push(this.active)}else this.stamp(p);this.paint();e.preventDefault()});listen('pointermove',e=>{if(!this.active)return;const p=this.point(e),last=this.active.points.at(-1);if(Math.hypot(p[0]-last[0],p[1]-last[1])>1.5&&this.active.points.length<3000)this.active.points.push(p);this.cursor=p;this.paint()});for(let n of['pointerup','pointercancel','lostpointercapture'])listen(n,()=>{if(this.active){this.active=null;this.changed()}});listen('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();let old=this.cursor,step=e.shiftKey?5:20;this.cursor=clampPoint(old[0]+(e.key==='ArrowRight'?step:e.key==='ArrowLeft'?-step:0),old[1]+(e.key==='ArrowDown'?step:e.key==='ArrowUp'?-step:0));if(this.pen){this.items.push({type:'stroke',color:this.color,width:this.width,points:[old,this.cursor]});this.changed()}this.paint(true)}else if(e.code==='Space'||e.key===' '){e.preventDefault();this.pen=!this.pen;this.onStatus(this.pen?'pen-down':'pen-up');this.paint(true)}else if(e.key==='Enter'){e.preventDefault();this.stamp(this.cursor);this.paint(true);this.changed()}});listen('focus',()=>this.paint(true));listen('blur',()=>{this.pen=false;this.paint()});this.paint();document.fonts?.ready.then(()=>{if(!this.abort.signal.aborted)this.paint()})}
 point(e){const r=this.canvas.getBoundingClientRect();return clampPoint((e.clientX-r.left)*800/r.width,(e.clientY-r.top)*500/r.height)}
 changed(){this.canvas.dataset.marks=String(this.items.length);this.onChange(this.items.length);this.onStatus('saved-in-session')}
 stamp(p=this.cursor){this.items.push({type:this.tool==='brush'?'circle':this.tool,color:this.color,x:p[0],y:p[1]});this.changed()}
 undo(){this.items.pop();this.paint();this.changed()}
 clear(){this.items=[];this.active=null;this.paint();this.changed()}
 guidePath(){const c=this.ctx;c.save();c.strokeStyle='#9da899';c.fillStyle='#c4c9bf';c.lineWidth=3;c.setLineDash([9,9]);c.lineCap='round';if(this.trace){c.setLineDash([]);c.textAlign='center';c.textBaseline='middle';c.font=`600 ${this.trace.length>4?130:240}px "Noto Sans Devanagari",Inter,sans-serif`;c.fillText(this.trace,400,270,700)}else if(this.guide==='circle'){c.beginPath();c.arc(400,250,150,0,Math.PI*2);c.stroke()}else if(this.guide==='house'){c.strokeRect(250,220,300,220);c.beginPath();c.moveTo(220,220);c.lineTo(400,80);c.lineTo(580,220);c.closePath();c.stroke();c.strokeRect(365,330,70,110);c.strokeRect(285,260,60,60);c.strokeRect(455,260,60,60)}else if(this.guide==='flower'){for(let i=0;i<6;i++){let a=i*Math.PI/3;c.beginPath();c.ellipse(400+65*Math.cos(a),200+65*Math.sin(a),55,35,a,0,Math.PI*2);c.stroke()}c.beginPath();c.arc(400,200,38,0,Math.PI*2);c.moveTo(400,240);c.lineTo(400,450);c.stroke()}else if(this.guide==='butterfly'){c.beginPath();c.moveTo(400,100);c.lineTo(400,410);c.ellipse(310,220,90,130,-.25,0,Math.PI*2);c.ellipse(490,220,90,130,.25,0,Math.PI*2);c.stroke()}else if(this.guide==='tree'){c.strokeRect(370,260,60,180);for(let[x,y,r]of[[330,220,80],[450,220,80],[400,145,90]]){c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke()}}else if(this.guide==='kite'){c.beginPath();c.moveTo(400,60);c.lineTo(530,220);c.lineTo(400,350);c.lineTo(270,220);c.closePath();c.moveTo(400,60);c.lineTo(400,350);c.moveTo(270,220);c.lineTo(530,220);c.moveTo(400,350);c.bezierCurveTo(300,400,500,420,400,480);c.stroke()}else if(this.guide==='pattern'){for(let i=0;i<5;i++){c.beginPath();c.arc(160+i*120,250,45,0,Math.PI*2);c.stroke()}}else{for(let i=0;i<4;i++){let y=100+i*100;c.beginPath();c.moveTo(100,y);if(i%2)c.bezierCurveTo(250,y-70,550,y+70,700,y);else c.lineTo(700,y);c.stroke()}}c.restore()}
 paint(cursor=false){this.canvas.dataset.marks=String(this.items.length);const c=this.ctx;c.clearRect(0,0,800,500);c.fillStyle='#fffdf5';c.fillRect(0,0,800,500);if(this.showGuide)this.guidePath();for(let item of this.items){c.save();c.strokeStyle=item.color;c.fillStyle=item.color;c.lineWidth=item.width||5;c.lineCap='round';c.lineJoin='round';if(item.type==='stroke'){c.beginPath();item.points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));if(item.points.length===1){c.arc(item.points[0][0],item.points[0][1],item.width/2,0,Math.PI*2);c.fill()}else c.stroke()}else if(item.type==='square')c.strokeRect(item.x-50,item.y-50,100,100);else if(item.type==='triangle'){c.beginPath();c.moveTo(item.x,item.y-60);c.lineTo(item.x+60,item.y+50);c.lineTo(item.x-60,item.y+50);c.closePath();c.stroke()}else{c.beginPath();c.arc(item.x,item.y,50,0,Math.PI*2);c.stroke()}c.restore()}if(cursor){c.save();c.strokeStyle='#293e34';c.lineWidth=2;c.setLineDash([4,4]);c.beginPath();c.arc(...this.cursor,12,0,Math.PI*2);c.moveTo(this.cursor[0]-18,this.cursor[1]);c.lineTo(this.cursor[0]+18,this.cursor[1]);c.moveTo(this.cursor[0],this.cursor[1]-18);c.lineTo(this.cursor[0],this.cursor[1]+18);c.stroke();c.restore()}}
 download(){this.paint(false);const link=document.createElement('a');link.download='my-drawing.png';link.href=this.canvas.toDataURL('image/png');link.click()}
 destroy(){this.abort.abort();this.active=null;this.pen=false}
}
